def esc(s):
    return s.replace('\\', '\\\\').replace('"', '\\"')

def build_block(locale):
    top: dict = {}
    for dotted, table in KEYS:
        parts = dotted.split('.')
        node = top
        for p in parts[:-1]:
            node = node.setdefault(p, {})
        node[parts[-1]] = table[locale]

    def render(node, indent):
        out = []
        pad = '  ' * indent
        for k, v in node.items():
            if isinstance(v, dict):
                out.append(f"{pad}{k}: {{")
                out.extend(render(v, indent + 1))
                out.append(f"{pad}}},")
            else:
                out.append(f'{pad}{k}: "{esc(v)}",')
        return out

    # render both namespaces as siblings
    out = []
    for ns in ("geminiSources", "geminiStudio"):
        if ns in top:
            out.append(f"  {ns}: {{")
            out.extend(render(top[ns], 2))
            out.append("  },")
    return "\n".join(out)

base = "frontend/src/lib/locales"
for loc in LOCALES:
    path = os.path.join(base, loc, "index.ts")
    with io.open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if "geminiSources:" in text:
        print(f"skip {loc} (already present)")
        continue
    anchor = "} satisfies TranslationShape;"
    idx = text.rfind(anchor)
    if idx == -1:
        # en-US defines the shape itself: insert before the closing "}" of
        # `export const enUS = { ... }` (the last line that is exactly "}").
        lines = text.split("\n")
        close = max(i for i, ln in enumerate(lines) if ln == "}")
        block = build_block(loc).split("\n")
        lines = lines[:close] + block + lines[close:]
        text = "\n".join(lines)
        with io.open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        print(f"ok {loc} (shape source, before closing brace line {close + 1})")
        continue
    block = build_block(loc) + "\n"
    text = text[:idx] + block + text[idx:]
    with io.open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print(f"ok {loc}")
